// Index popup of the pages generated by haunt.scm: the Geopages list on
// the home page, and the "Site index" of this repo's own Geopage (the page
// and its sections). The same behavior as the index popup of the repo
// pages (_layouts/default.html), minus fetching other pages: the list is
// already in the markup, so this only opens and closes it, expands and
// collapses a page's sections, and lets the arrow keys walk it. Kept out
// of haunt.scm because Haunt escapes &, < and > inside inline scripts.
(function () {
    var btn = document.getElementById('nav-toggle');
    var dialog = document.getElementById('nav-dialog');
    var tree = document.getElementById('nav-tree');

    // A page with sections has a triangle (.nav-expand) before its link;
    // the home page's entries don't, so none of this applies there.
    function expander(li) {
        return li && li.querySelector(':scope > .nav-expand');
    }
    function setExpanded(li, on) {
        expander(li).setAttribute('aria-expanded', on);
        var ul = li.querySelector(':scope > .nav-headings');
        if (ul) ul.hidden = !on;
    }
    function isExpanded(li) {
        return expander(li).getAttribute('aria-expanded') === 'true';
    }
    tree.addEventListener('click', function (e) {
        var b = e.target.closest('.nav-expand');
        if (b) setExpanded(b.parentNode, !isExpanded(b.parentNode));
    });

    function open() {
        dialog.showModal();
        // Focus the list rather than a link, so Tab starts from
        // the top without a focus ring showing up on open. Without
        // preventScroll, focusing the list (taller than the popup) would
        // scroll the popup down to it, past the header.
        tree.focus({ preventScroll: true });
    }
    btn.hidden = false;
    // The shortcut takes Cmd on macOS (see keydown below), so say so.
    var platform = (navigator.userAgentData && navigator.userAgentData.platform) || navigator.platform;
    if (/mac|iphone|ipad/i.test(platform)) btn.querySelector('kbd').textContent = '⌘ K';
    btn.addEventListener('click', open);
    dialog.querySelector('.nav-close').addEventListener('click', function () { dialog.close(); });
    // Leaving the page closes the popup, so that coming back to it (browser
    // back/forward restores the page as it was left) doesn't find it still
    // open. At once, without the fade, which the restored page would replay.
    window.addEventListener('pagehide', function () {
        if (!dialog.open) return;
        dialog.classList.add('nav-instant');
        dialog.close();
    });
    window.addEventListener('pageshow', function () { dialog.classList.remove('nav-instant'); });
    // Clicks on the backdrop land on the <dialog> itself, since
    // .nav-dialog-inner covers all of its content box.
    // A section link only scrolls this page, so it closes the popup too.
    dialog.addEventListener('click', function (e) {
        if (e.target === dialog) dialog.close();
        else if (e.target.closest('a[href^="#"]')) dialog.close();
    });
    // Over the popup, the wheel scrolls the popup or nothing: without
    // this it falls through to the page whenever the popup has nothing
    // (left) to scroll, since overscroll-behavior only covers the latter
    // case. Over the backdrop the page still scrolls.
    dialog.addEventListener('wheel', function (e) {
        if (e.target === dialog || !e.deltaY) return;
        var atTop = dialog.scrollTop <= 0;
        var atBottom = dialog.scrollTop + dialog.clientHeight >= dialog.scrollHeight - 1;
        if ((e.deltaY < 0 && atTop) || (e.deltaY > 0 && atBottom)) e.preventDefault();
    }, { passive: false });
    // Up/down walk the visible entries, Home/End jump to their ends; right
    // expands a page's sections or steps into them, left collapses them or
    // goes back up to the page. Enter is native.
    tree.addEventListener('keydown', function (e) {
        if (e.altKey || e.ctrlKey || e.metaKey) return;
        var items = Array.prototype.filter.call(tree.querySelectorAll('a'), function (a) {
            return !a.closest('ul[hidden]');
        });
        var cur = document.activeElement;
        var i = items.indexOf(cur);
        var page = i >= 0 && expander(cur.parentNode) ? cur.parentNode : null;
        var next;
        switch (e.key) {
            case 'ArrowDown': next = i < 0 ? items[0] : items[i + 1]; break;
            case 'ArrowUp': next = i < 0 ? items[items.length - 1] : items[i - 1]; break;
            case 'Home': next = items[0]; break;
            case 'End': next = items[items.length - 1]; break;
            case 'ArrowRight':
                if (!page) return;
                if (isExpanded(page)) next = items[i + 1];
                else setExpanded(page, true);
                break;
            case 'ArrowLeft':
                if (i < 0) return;
                if (page && isExpanded(page)) {
                    setExpanded(page, false);
                    break;
                }
                var parent = cur.closest('li').parentNode.closest('li');
                if (!parent) return;
                next = parent.querySelector('a');
                break;
            default: return;
        }
        e.preventDefault();
        if (next) next.focus();
    });
    document.addEventListener('keydown', function (e) {
        if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k') {
            e.preventDefault();
            if (dialog.open) dialog.close();
            else open();
        }
    });
})();
